package com.codeguardian.controller; import com.codeguardian.service.rag.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/rag") @RequiredArgsConstructor public class RagController{private final HybridRetrievalService rag;@GetMapping("/search") public List<KnowledgeDocument> search(@RequestParam String query,@RequestParam(defaultValue="3")int limit){return rag.search(query,limit);}@GetMapping("/context") public Map<String,String> context(@RequestParam String query){return Map.of("context",rag.context(query));}}
